                                                                         ※ 추상 클래스는 내부에 실행 코드가 없는 추
  ❺      public String getName() {
                                                                            상 메소드를 포함하기 때문에 객체 변수의
  ❻               return "Vehicle name : " + name;
                                                                            생성자로 사용할 수 없다.
           }
                                                                           예) Vehicle obj = new Vehicle(); - ×
  }
  class Car extends Vehicle {
